class Rectangle
  def initialize(width, height)
    @width = width
    @height = height
  end

  def area = @width * @height
end

class Triangle
  def initialize(base, height)
    @base = base
    @height = height
  end

  def area = @base * @height / 2
end

# Duck typing: no shared superclass or interface is needed to call #area.
[Rectangle.new(3, 4), Triangle.new(10, 3)].each do |shape|
  puts "#{shape.class}: #{shape.area}"
end
